CREATE TABLE IF NOT EXISTS bridge_users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, email VARCHAR(190) NULL UNIQUE, name VARCHAR(100) NOT NULL, role VARCHAR(16) NOT NULL DEFAULT 'student', created_at BIGINT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS bridge_courses (id VARCHAR(40) PRIMARY KEY, title VARCHAR(150) NOT NULL, description TEXT NOT NULL, code VARCHAR(80) NOT NULL UNIQUE, end_at BIGINT NOT NULL, image VARCHAR(30) NOT NULL DEFAULT 'hero') ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS bridge_memberships (user_id BIGINT UNSIGNED NOT NULL, course_id VARCHAR(40) NOT NULL, PRIMARY KEY(user_id,course_id), FOREIGN KEY(user_id) REFERENCES bridge_users(id), FOREIGN KEY(course_id) REFERENCES bridge_courses(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS bridge_lessons (id VARCHAR(40) PRIMARY KEY, course_id VARCHAR(40) NOT NULL, title VARCHAR(150) NOT NULL, start_at BIGINT NOT NULL, end_at BIGINT NOT NULL, teacher VARCHAR(150) NOT NULL, address VARCHAR(300) NOT NULL DEFAULT '', url VARCHAR(2000) NOT NULL DEFAULT '', description TEXT NOT NULL, homework TEXT NOT NULL, image VARCHAR(100) NOT NULL DEFAULT 'hero', cancelled TINYINT NOT NULL DEFAULT 0, FOREIGN KEY(course_id) REFERENCES bridge_courses(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS bridge_attendance (user_id BIGINT UNSIGNED NOT NULL, lesson_id VARCHAR(40) NOT NULL, format VARCHAR(10) NOT NULL, updated_at BIGINT NOT NULL, PRIMARY KEY(user_id,lesson_id), FOREIGN KEY(user_id) REFERENCES bridge_users(id), FOREIGN KEY(lesson_id) REFERENCES bridge_lessons(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS bridge_homework (user_id BIGINT UNSIGNED NOT NULL, lesson_id VARCHAR(40) NOT NULL, body TEXT NOT NULL, done TINYINT NOT NULL DEFAULT 0, comment TEXT NOT NULL, updated_at BIGINT NOT NULL, PRIMARY KEY(user_id,lesson_id), FOREIGN KEY(user_id) REFERENCES bridge_users(id), FOREIGN KEY(lesson_id) REFERENCES bridge_lessons(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS bridge_feedback (id VARCHAR(40) PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, lesson_id VARCHAR(40) NOT NULL, takeaway TEXT NOT NULL, impression TEXT NOT NULL, question TEXT NOT NULL, liked TEXT NOT NULL, wishes TEXT NOT NULL, visibility VARCHAR(10) NOT NULL, created_at BIGINT NOT NULL, UNIQUE KEY feedback_once(user_id,lesson_id), FOREIGN KEY(user_id) REFERENCES bridge_users(id), FOREIGN KEY(lesson_id) REFERENCES bridge_lessons(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS bridge_replies (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, feedback_id VARCHAR(40) NOT NULL, user_id BIGINT UNSIGNED NOT NULL, body TEXT NOT NULL, created_at BIGINT NOT NULL, FOREIGN KEY(feedback_id) REFERENCES bridge_feedback(id), FOREIGN KEY(user_id) REFERENCES bridge_users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS bridge_notifications (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, lesson_id VARCHAR(40) NOT NULL, body VARCHAR(1000) NOT NULL, is_read TINYINT NOT NULL DEFAULT 0, created_at BIGINT NOT NULL, FOREIGN KEY(user_id) REFERENCES bridge_users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS bridge_limits (bucket VARCHAR(150) PRIMARY KEY, hits INT NOT NULL DEFAULT 0, expires_at BIGINT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS bridge_audit (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, actor_id BIGINT UNSIGNED NOT NULL, subject_id BIGINT UNSIGNED NOT NULL, lesson_id VARCHAR(40) NOT NULL, before_value VARCHAR(10) NOT NULL, after_value VARCHAR(10) NOT NULL, created_at BIGINT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS bridge_outbox (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, body TEXT NOT NULL, attempts INT NOT NULL DEFAULT 0, available_at BIGINT NOT NULL, sent_at BIGINT NULL, lease_until BIGINT NOT NULL DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS bridge_rewards (user_id BIGINT UNSIGNED NOT NULL, lesson_id VARCHAR(40) NOT NULL, creature INT NOT NULL, PRIMARY KEY(user_id,lesson_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS bridge_credentials (
 user_id BIGINT UNSIGNED PRIMARY KEY,
 login VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL UNIQUE,
 password_hash VARCHAR(255) NOT NULL,
 recovery_hash VARCHAR(64) NOT NULL,
 auth_version INT UNSIGNED NOT NULL DEFAULT 1,
 reset_hash VARCHAR(64) NULL,
 reset_expires_at BIGINT NULL,
 FOREIGN KEY(user_id) REFERENCES bridge_users(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
